
// Populate the HTML template sections with the corresponding app data
!function populateSections (app_info) {
  for (let key in app_info) {
    let section = document.getElementById (key)
    let entries = app_info[key]
    if (!Array.isArray(entries)) continue
    if (entries?.length) {
      let list = section.querySelector('ul')
      let li = list.innerHTML, html = ''
      for (let each of entries)
        html += li.replace(/\$\{(\w+)\}/g, (_,p) => each[p]||'')
      list.innerHTML = html
    } else section.style.display = 'none'
  }
} (document.app_info)


// Set initial theme based on saved preference or system setting
try {
  const theme = localStorage.getItem('cds.index.theme')
  const dark = theme ? theme === 'dark' : window.matchMedia('(prefers-color-scheme: dark)').matches
  document.documentElement.dataset.theme = dark ? 'dark' : 'light'
} catch {/* ignore errors */}


// Ensure all external links open safely in a new tab
function applySafeRel () {
  document.querySelectorAll('a[target="_blank"]:not([rel])').forEach(link => {
    link.setAttribute('rel', 'noopener noreferrer');
  });
}
applySafeRel();


const OPEN_KEY  = 'cds.index.open'
const THEME_KEY = 'cds.index.theme'
const themeSwitch = document.getElementById('theme-switch')
const detailsIn = id => document.querySelectorAll(`#${id} details:not(.data-preview)`)
const details = () => document.querySelectorAll('details:not(.data-preview)')

function makeToggle(groupId) {
  const button = document.querySelector(`#${groupId} .toggle-button`); if (!button) return
  const update = () => {
    const expand = [...detailsIn(groupId)].some(d => !d.open)
    button.textContent = expand ? '⊞' : '⊟'
    button.setAttribute('aria-label', expand ? 'Expand all' : 'Collapse all')
    button.title = expand ? 'Expand all' : 'Collapse all'
  }
  button.addEventListener('click', () => {
    const expand = [...detailsIn(groupId)].some(d => !d.open)
    detailsIn(groupId).forEach(d => { d.open = expand })
    update()
  })
  document.getElementById(groupId).addEventListener('toggle', () => {
    try {
      const state = {}
      details().forEach(d => { if (d.open) state[d.id] = true })
      localStorage.setItem(OPEN_KEY, JSON.stringify(state))
    } catch {/* ignore errors */}
    update()
  }, true)
  update()
}

themeSwitch.checked = document.documentElement.dataset.theme === 'dark'
themeSwitch.addEventListener('change', () => {
  const theme = themeSwitch.checked ? 'dark' : 'light'
  document.documentElement.dataset.theme = theme
  try {
    localStorage.setItem(THEME_KEY, theme)
  } catch {/* ignore errors */}
})
document.addEventListener('keydown', e => {
  if (e.key === '#') {
    e.preventDefault()
    themeSwitch.checked = !themeSwitch.checked
    themeSwitch.dispatchEvent(new Event('change')) // eslint-disable-line no-undef
  } else if (e.key === '+') {
    e.preventDefault()
    document.querySelector('#provided-services .toggle-button').click()
  } else if (e.key === '*') {
    e.preventDefault()
    document.querySelector('#required-services .toggle-button')?.click()
  }
})

// ── Open/close state ──
try {
  const saved = JSON.parse(localStorage.getItem(OPEN_KEY) || '{}')
  details().forEach(d => { if (saved[d.id]) d.open = true })
} catch {/* ignore errors */}

makeToggle('provided-services')
makeToggle('required-services')

// Hide services sections (e.g. Required Services) that have no entries
document.querySelectorAll('.services').forEach(section => {
  if (!section.querySelector('details')) section.style.display = 'none'
})

function selectProtocol(d, proto) {
  const protos = d.dataset.protocols?.split(' ') || []
  const idx = protos.indexOf(proto)
  if (idx < 0) return false
  const paths = JSON.parse(d.dataset.paths || '[]')
  const base = paths[idx]
  if (!base) return false
  d.dataset.selectedProtocol = proto
  d.querySelectorAll('.protocol-badges [role="radio"]').forEach(button => {
    const selected = button.dataset.protocol === proto
    button.setAttribute('aria-checked', selected ? 'true' : 'false')
    button.tabIndex = selected ? 0 : -1
  })
  d.querySelectorAll('a.entity-name[data-base]').forEach(a => {
    const dataPath = base + '/' + a.dataset.base
    // Operations (actions/functions) live in <li class="operation"> and link to their raw URL;
    // entities go through the client-side table renderer page.
    const isOperation = a.closest('li.operation')
    if (isOperation) { a.href = dataPath; return }
    // Always pass a full absolute URL to the table page — remote services already carry an
    // origin; local paths are resolved against the current origin.
    const url = /^https?:\/\//.test(dataPath)
      ? dataPath
      : new URL('/' + dataPath.replace(/^\//, ''), location.origin).href
    a.href = '/.cap/table.html?url=' + encodeURIComponent(url)
    a.target = '_blank'
  })
  const descLink = d.querySelector('a.describe-link')
  if (descLink) {
    const describes = JSON.parse(descLink.dataset.describes || '[]')
    const labels = JSON.parse(descLink.dataset.labels || '[]')
    const titles = JSON.parse(descLink.dataset.titles || '[]')
    const url = describes[idx]
    if (url) {
      descLink.href = url
      descLink.querySelector('.label').textContent = labels[idx] ?? 'metadata'
      const title = titles[idx]
      if (title) descLink.title = title
      else descLink.removeAttribute('title')
      descLink.hidden = false
    } else descLink.hidden = true
  }
  d.querySelectorAll('a[data-protocols]').forEach(a => {
    const protocols = a.dataset.protocols.split(' ')
    a.hidden = !a.hasAttribute('data-always') && !protocols.includes(proto)
  })
  return true
}

document.addEventListener('click', e => {
  const protocolButton = e.target.closest('.protocol-badges [role="radio"]')
  if (!protocolButton) return
  e.preventDefault()
  e.stopPropagation()
  selectProtocol(protocolButton.closest('details'), protocolButton.dataset.protocol)
})

document.querySelectorAll('details:not(.data-preview)').forEach(d => {
  selectProtocol(d, d.dataset.selectedProtocol)
})

// Dynamically created table-view links get target="_blank"; apply safe rel to them too.
applySafeRel()
